@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Shipment Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

<div class="mb-3 row">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary" @onclick="LoadShipments">Refresh</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match the current filter.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToShortDateString()</td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@((int)shipment.Status)"
                                @onchange="e => UpdateStatus(shipment, e)">
                            @foreach (var s in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)s)">@s</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = "";
    private string statusFilter = "";

    private IEnumerable<Shipment> FilteredShipments => shipments?.Where(s =>
        (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
    ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider
@rendermode InteractiveAuto

<PageTitle>Track My Shipments</PageTitle>

<h1>Track Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number..." @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (searchedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>Tracking: @searchedShipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @searchedShipment.Origin</p>
                    <p><strong>To:</strong> @searchedShipment.Destination</p>
                    <p><strong>Description:</strong> @searchedShipment.Description</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge @GetStatusBadge(searchedShipment.Status)">@searchedShipment.Status</span></p>
                    <p><strong>Shipped:</strong> @searchedShipment.ShippedDate.ToShortDateString()</p>
                    <p><strong>Estimated Delivery:</strong> @searchedShipment.EstimatedDelivery.ToShortDateString()</p>
                </div>
            </div>
        </div>
    </div>
}
else if (searched)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

<h2 class="mt-4">My Shipments</h2>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments on record.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@shipment.TrackingNumber</h5>
                        <p class="card-text">
                            <strong>To:</strong> @shipment.Destination<br />
                            <strong>Status:</strong> <span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span><br />
                            <strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToShortDateString()
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? searchedShipment;
    private bool searched;
    private List<Shipment>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? "";
        myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
    }

    private async Task TrackShipment()
    {
        searched = true;
        searchedShipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            searchedShipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

