using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.Select(MapToModel()).ToListAsync();
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments
            .Where(s => s.TrackingNumber == trackingNumber)
            .Select(MapToModel())
            .FirstOrDefaultAsync();
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .Select(MapToModel())
            .ToListAsync();
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = status;
            await db.SaveChangesAsync();
        }
    }

    private static System.Linq.Expressions.Expression<Func<ShipmentEntity, Shipment>> MapToModel() => e => new Shipment
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Controllers;

[ApiController]
[Route("api/shipments")]
[Authorize]
public class ShipmentsController(IShipmentService shipmentService) : ControllerBase
{
    [HttpGet]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<List<Shipment>>> GetAll()
    {
        return await shipmentService.GetAllShipmentsAsync();
    }

    [HttpGet("track/{trackingNumber}")]
    public async Task<ActionResult<Shipment>> GetByTracking(string trackingNumber)
    {
        var shipment = await shipmentService.GetByTrackingNumberAsync(trackingNumber);
        if (shipment is null) return NotFound();
        return shipment;
    }

    [HttpGet("customer/{email}")]
    public async Task<ActionResult<List<Shipment>>> GetByCustomer(string email)
    {
        return await shipmentService.GetShipmentsByCustomerAsync(email);
    }

    [HttpPut("{id}/status/{status}")]
    [Authorize(Roles = "Dispatcher")]
    public async Task<IActionResult> UpdateStatus(int id, ShipmentStatus status)
    {
        await shipmentService.UpdateStatusAsync(id, status);
        return NoContent();
    }
}

using Microsoft.AspNetCore.Identity;
